blocks.styl:
.white-bg { background:#fff }
.title { color:#2473d7;font-size:24px;font-weight:500;line-height:32px;padding-top:30px;padding-bottom:25px }
@media screen and (max-width:600px) {
  .title { padding-left:20px!important;padding-right:20px!important }
}
.text { color:#5b6e88;font-size:16px;font-weight:400;line-height:24px;padding-bottom:20px }
@media screen and (max-width:600px) {
  .text { padding-left:20px!important;padding-right:20px!important }
}
.text a { color:#2473d7;text-decoration:underline }
.text.bold { font-weight:700 }

.white-bg { background:#fff }
table[class=body] table.columns td.first-td { max-width:100%;height:40px;vertical-align:middle;padding-left:20px;padding-right:20px;border:1px solid #5b6e88;padding-bottom:0!important;border-collapse:collapse }
@media screen and (max-width:600px) {
  table[class=body] table.columns td.first-td { padding-left:10px!important;padding-right:10px!important;width:150px!important }
}
table[class=body] table.columns td.last-td { max-width:100%;height:40px;line-height:40px;vertical-align:middle;padding-left:20px;padding-right:20px;border:1px solid #5b6e88;padding-bottom:0!important;border-collapse:collapse }
@media screen and (max-width:600px) {
  table[class=body] table.columns td.last-td { padding-left:10px!important;padding-right:10px!important;width:150px!important }
}
.table-title { color:#5b6e88;font-size:16px;font-weight:700;padding:10px 0 }
.asterisk,.table-text { color:#5b6e88;font-size:16px;font-weight:400 }

